BEGIN;
CREATE SEQUENCE IF NOT EXISTS delayed_debit_note_seq START 1;
CREATE TABLE IF NOT EXISTS delayed_payment_settings(id SMALLINT PRIMARY KEY DEFAULT 1 CHECK(id=1),daily_rate_percent NUMERIC(8,5) NOT NULL DEFAULT 0.1 CHECK(daily_rate_percent>=0),grace_period_days INTEGER NOT NULL DEFAULT 0 CHECK(grace_period_days>=0),calculation_base TEXT NOT NULL DEFAULT 'Invoice Value Excluding GST',partial_payment_treatment TEXT NOT NULL DEFAULT 'Remaining Outstanding Principal',tax_treatment TEXT NOT NULL DEFAULT 'As Applicable',debit_note_prefix TEXT NOT NULL DEFAULT 'DN',due_soon_days INTEGER NOT NULL DEFAULT 3,significant_delay_days INTEGER NOT NULL DEFAULT 30,updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ DEFAULT now());
INSERT INTO delayed_payment_settings(id)VALUES(1)ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS delayed_payment_accounts(id BIGSERIAL PRIMARY KEY,receivable_id BIGINT NOT NULL UNIQUE REFERENCES finance_receivable_invoices(id) ON DELETE RESTRICT,buyer_id BIGINT NOT NULL REFERENCES buyers(id) ON DELETE RESTRICT,order_id BIGINT REFERENCES orders(id) ON DELETE RESTRICT,buyer_gst TEXT,invoice_value NUMERIC(16,2) NOT NULL,gst_amount NUMERIC(16,2) NOT NULL DEFAULT 0,value_excluding_gst NUMERIC(16,2) NOT NULL,delivery_date DATE NOT NULL,payment_terms TEXT,credit_days INTEGER NOT NULL DEFAULT 0,due_date DATE NOT NULL,grace_period_days INTEGER NOT NULL DEFAULT 0,first_chargeable_date DATE NOT NULL,payment_status TEXT NOT NULL DEFAULT 'Outstanding',settled_at DATE,remarks TEXT,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS delayed_payment_accruals(id BIGSERIAL PRIMARY KEY,account_id BIGINT NOT NULL REFERENCES delayed_payment_accounts(id) ON DELETE RESTRICT,accrual_date DATE NOT NULL,overdue_day_number INTEGER NOT NULL,applicable_principal NUMERIC(16,2) NOT NULL,daily_rate_percent NUMERIC(8,5) NOT NULL,daily_charge NUMERIC(16,2) NOT NULL,cumulative_accrued NUMERIC(16,2) NOT NULL,payment_adjustment NUMERIC(16,2) NOT NULL DEFAULT 0,debit_note_adjustment NUMERIC(16,2) NOT NULL DEFAULT 0,calculation_base TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(account_id,accrual_date));
CREATE TABLE IF NOT EXISTS delayed_payment_debit_notes(id BIGSERIAL PRIMARY KEY,system_reference TEXT NOT NULL UNIQUE DEFAULT('DND-'||lpad(nextval('delayed_debit_note_seq')::text,7,'0')),debit_note_number TEXT UNIQUE,account_id BIGINT NOT NULL REFERENCES delayed_payment_accounts(id) ON DELETE RESTRICT,amount NUMERIC(16,2) NOT NULL CHECK(amount>0),status TEXT NOT NULL DEFAULT 'Pending Final Approval' CHECK(status IN('Debit Note Draft','Pending Final Approval','Approved','Rejected','Cancelled')),generated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,generated_at TIMESTAMPTZ DEFAULT now(),approved_by INTEGER REFERENCES users(id) ON DELETE SET NULL,approval_date TIMESTAMPTZ,approval_remarks TEXT,rejection_reason TEXT,debit_note_date DATE,document_html TEXT,version_number INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_delayed_pending_note ON delayed_payment_debit_notes(account_id)WHERE status IN('Debit Note Draft','Pending Final Approval');
CREATE TABLE IF NOT EXISTS delayed_payment_audit(id BIGSERIAL PRIMARY KEY,account_id BIGINT REFERENCES delayed_payment_accounts(id) ON DELETE RESTRICT,debit_note_id BIGINT REFERENCES delayed_payment_debit_notes(id) ON DELETE RESTRICT,event_type TEXT NOT NULL,old_values JSONB,new_values JSONB,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,occurred_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_delayed_accounts_due ON delayed_payment_accounts(due_date,payment_status);
CREATE INDEX IF NOT EXISTS idx_delayed_accrual_history ON delayed_payment_accruals(account_id,accrual_date DESC);
CREATE INDEX IF NOT EXISTS idx_delayed_notes_status ON delayed_payment_debit_notes(status,generated_at DESC);
COMMIT;
